-- Esthemax CMS: run this once in Supabase, SQL Editor, then press Run.
-- Safe to run again later: it only updates what is already there.

-- 1. One table holds every kind of content (masks, skincare, sets, posts, contact details).
create table if not exists public.content (
  kind text not null,
  id text not null,
  ord integer not null default 0,
  data jsonb not null,
  updated_at timestamptz not null default now(),
  primary key (kind, id)
);

-- 2. Rules: anyone can read, only staff who are logged in can change anything.
alter table public.content enable row level security;
drop policy if exists "content public read" on public.content;
create policy "content public read" on public.content for select using (true);
drop policy if exists "content staff write" on public.content;
create policy "content staff write" on public.content for all to authenticated using (true) with check (true);

-- 3. Photo storage: a public bucket called media; only staff can upload.
  on conflict (id) do update set public = true;
drop policy if exists "media public read" on storage.objects;
create policy "media public read" on storage.objects for select using (bucket_id = 'media');
drop policy if exists "media staff insert" on storage.objects;
create policy "media staff insert" on storage.objects for insert to authenticated with check (bucket_id = 'media');
drop policy if exists "media staff update" on storage.objects;
create policy "media staff update" on storage.objects for update to authenticated using (bucket_id = 'media');
drop policy if exists "media staff delete" on storage.objects;
create policy "media staff delete" on storage.objects for delete to authenticated using (bucket_id = 'media');

-- 4. Today's products and posts, so nothing is lost.
on conflict (kind, id) do update set data = excluded.data, ord = excluded.ord, updated_at = now();
