insert into public.content (kind, id, ord, data) values
('mask', '771', 0, '{"code":"771","name":"Antioxidant Goji","dot":"#C94F60","tags":"Renew · Protect","cats":["brighten"],"img":"assets/products/us/771.jpg","desc":"BENEFITS – Rich in antioxidants to help eliminate free radicals and damage to the skin. – Promotes anti-aging and anti-oxidant properties due to its high concentration of Vitamin C. – Promotes a translucent, lustrous and even-toned complexion – Helps facilitate skin repair by promoting dermis and epidermis regeneration. – Improves skin vitality and energy. – Increases collagen levels and boosts skin fullness.","concerns":"Antioxidant, Dullness, Fine Lines, Uneven Skin Tone, Dryness.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Avena Sativa (Oat) Kernel Flour, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, Actinidia Chinensis (Kiwi) Seed, *Lycium\u0003 Barbarum (Goji Berry) Fruit Extract, *Punica Granatum (Pomegranate) Fruit Extract, Calcium Sulfate, Diatomaceous Earth, Sodium\u0003 Chloride, Magnesium Sulfate, Potassium Chloride, Iron Oxides, Fragrance. *Certified Organic Ingredients."}'::jsonb),
('mask', '772', 1, '{"code":"772","name":"Super Greens Strength","dot":"#2E6E4E","tags":"Detox · Energize","cats":["clarify"],"img":"assets/products/us/772.jpg","desc":"BENEFITS – Rich in micronutrients, flavonoids and phytonutrients to increase energy, restore PH balance, and help synthesize proteins. – Manages dry skin by balancing oil and water distribution. – Reduces the appearance of dark circles and sagging. – Supports firming and tightening, and protects the skin from environmental stressors. – Phytonutrients and flavonoids help prevent visible signs of aging.","concerns":"Dullness, Dryness, Dark Circles, Acne, Sensitive.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, Glucose, *Avena Sativa (Oat) Kernel Flour, *Cocos Nucifera (Coconut) \u0003Fruit Powder, *Salix Alba (Willow) Bark Extract, Actinidia Chinensis (Kiwi) Seed, *Brassica Oleracea Acephala Leaf Extract, *Spinacia Oleracea (Spinach) Leaf\u0003 Extract, *Medicago Sativa (Alfalfa) Extract, *Spirulina Platensis Powder, *Moringa Oleifera Leaf Powder, *Hordeum Distichon (Barley) Extract, *Plantago Asiatica\u0003 Extract, *Malpighia Glabra (Acerola) Fruit Extract, *Adansonia Digitata (Baobab) Leaf Extract, *Olea Europaea (Olive) Fruit Extract, Calcium Sulfate, Diatoma\u0003ceous Earth, Sodium Chloride, Magnesium Sulfate, Potassium Chloride, Iron Oxides, Chromium Oxide Greens, Fragrance. *Certified Organic Ingredients."}'::jsonb),
('mask', '773', 2, '{"code":"773","name":"Brightening Complex","dot":"#D8B22E","tags":"Brighten · Even","cats":["brighten","clarify"],"img":"assets/products/us/773.jpg","desc":"BENEFITS – Reduce pigmentations and lightens skin tone overall. – emits over-production of melanin. – inhibits the intensification of tyrosinase. – Illuminates the skin to reveal a subtle glow. – Reduces pigmentation and diminishes the appearance of age spots, blemishes and discolouration. – Promote a translucent, lustrous, and even-toned complexion.","concerns":"Uneven Skin Tone, Discolorations, Hyperpigmentation, Dark Spots.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Avena Sativa (Oat) Kernel Flour, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, *Citrus Limon (Lemon) Fruit Extract, Glutathione, Calcium Sulfate, Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate, Potassium Chloride, Iron Oxides, Fragrance. *Certified Organic Ingredients."}'::jsonb),
('mask', '774', 3, '{"code":"774","name":"Belgium Cacao","dot":"#C86E3E","tags":"Hydrate · Indulge","cats":["hydrate"],"img":"assets/products/us/774.jpg","desc":"BENEFITS – Increases skin energy to promote a overall glowing apperance. – Returns vigour to dry and aged skin. – Promotes a smooth, translucent skin complexion. – Leaves skin looking young and radiant. – Smooths skin,makingit look and feel velvety soft.","concerns":"Antioxidant, Dullness, Uneven Texture, Sensitive.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Avena Sativa (Oat) Kernel Flour, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, Theobroma Cacao (Cocoa) Seed Extract, Calcium Sulfate, Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate, Potassium Chloride, Chromium Oxide Greens, Iron Oxides, Fragrance.*Certified Organic Ingredients."}'::jsonb),
('mask', '775', 4, '{"code":"775","name":"Egyptian Rose","dot":"#8E5AA8","tags":"Hydrate · Comfort","cats":["hydrate","calm"],"img":"assets/products/us/775.jpg","desc":"BENEFITS – Illuminates the skin to reveal a subtle glow. ‘Keeps skin hydrated throughout the day. – Returns skin firmness and suppleness while reducing the appearance of fine lines and wrinkles. – Reduces the appearance of hyperpigmentation and diminishes the appearance of age spots, blemishes and discoloration.","concerns":"Fine Lines, Uneven Skin Tone, Dullness, Dryness, Sensitive.","ingredients":"Potassium Alginate, Algin, Rosa Centifolia Flower, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Avena Sativa (Oat) Kernel Flour, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark \u0003Extract, *Rosa Centifolia Flower Extract, Calcium Sulfate, Diatomaceous Earth, Sodium Chloride, Magnesium \u0003Sulfate, Potassium Chloride, Fragrance. *Certified Organic Ingredients."}'::jsonb),
('mask', '776', 5, '{"code":"776","name":"Pure Himalayan White Tea","dot":"#E38FB0","tags":"Clarify · Soothe","cats":["clarify","calm"],"img":"assets/products/us/776.jpg","desc":"BENEFITS – Naturally detoxifies. – Minimizes skin irritation, rashes, inflammation, and redness. Improves physical vitality and energy. – Regulates the skin’s natural sebum production and reduces open pores. ‘Promotes a smooth, translucent skin complexion. – Returns vigour to dry, aged skin. – Evens complexion and gives skin a youthful glow.","concerns":"Sensitive, Redness, Eczema, Rosacea, Dullness, Anti-Inflammatory.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Avena Sativa (Oat) Kernel Flour, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, *Camellia Sinensis (White Tea) Leaf Extract, *Linum Usitatissimum (Linseed) Seed Flour, Calcium Sulfate, Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate, Potassium Chloride, Iron Oxides, Fragrance. *Certified Organic Ingredients."}'::jsonb),
('mask', '777', 6, '{"code":"777","name":"Resilience Caviar","dot":"#D04E78","tags":"Firm · Fortify","cats":["firm"],"img":"assets/products/us/777.jpg","desc":"BENEFITS – Enhance collagen production and elastin/fibroblast reproduction. ‘Boosts epidermal skin cell ceramide production. – Reverses signs of aging process by enhancing and promoting cell renewal. ‘Enriched with nutrients and amino acids to boost skin cell function. – Helps reduces the appearance and deepening of lines and wrinkles. – Increases skin elasticity thereby reducing the appearance of saggy skin. ‘Reduces the appearance of pores and evens tone.","concerns":"Fine Lines & Wrinkles, Dull & Sagging, Loss of Firmness & Elasticity.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Avena Sativa (Oat) Kernel Flour, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, *Linum Usitatissimum (Linseed) Seed Flour, Sodium Chloride, Calcium Sulfate, Diatomaceous Earth, Magnesium Sulfate, Caviar Extract, Potassium Chloride, Ultramarines, Fragrance. *Certified Organic Ingredients."}'::jsonb),
('mask', '778', 7, '{"code":"778","name":"Australian Sheep Placenta","dot":"#B89A6A","tags":"Nourish · Support","cats":["firm"],"img":"assets/products/us/778.jpg","desc":"BENEFITS – Reduces skin sagging by stimulating collagen production for firmer-looking skin. ‘Helps to firm and tighten skin by providing building blocks of protein. – Acts as a free radical scavenger, protecting cells from oxidative harm caused by free radicals. Less oxidative harm results in fewer fine lines and wrinkles. – Decreases large pores and promotes healing. – Enhances the skin renewal process and reduces the appearance of scars. ‘Increases skin elasticity thereby reducing the appearance of saggy skin.","concerns":"Loss of Firmness & Elasticity, Anti-Aging, Fine Lines & Wrinkles, All Skin Types.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Avena Sativa (Oat) Kernel Flour, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, Ovine (sheep) \u0003Placenta, Sodium Chloride, Magnesium Sulfate, Calcium Sulfate, Diatomaceous Earth, Mica, Potassium Chloride, Gold (24K), Fragrance. *Certified Organic Ingredients."}'::jsonb),
('mask', '779', 8, '{"code":"779","name":"Renewal Boost","dot":"#8A5A3E","tags":"Renew · Rejuvenate","cats":["firm"],"img":"assets/products/us/779.jpg","desc":"BENEFITS – Aids renewal and repair of damaged cells. – Stimulates skin cell renewal by reinvigorating old cells and generating new healthy cells. – Supports natural skin repair and the natural release of adult stem cells in skin tissue. – Increases collagen levels and boosts skin fullness. – Promotes gentle cell turnover.","concerns":"Fine Lines, Wrinkles, Elasticity, Loss of Firmness.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Avena Sativa (Oat) Kernel Flour, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, Aphanizomenon\u0003Flos-Aquae Extract, Calcium Sulfate, Diatomaceous Earth, Mica, Sodium Chloride, Magnesium Sulfate, Potassium Chloride, Diamond Powder, Fragrance. *Certified Organic Ingredients."}'::jsonb),
('mask', '780', 9, '{"code":"780","name":"Radiance Biotin","dot":"#2FA8A0","tags":"Strengthen · Enhance","cats":["hydrate"],"img":"assets/products/us/780.jpg","desc":"BENEFITS – Keeps skin moisturized and prevents cracking. ‘Balances sensitive,dull,and problematic skin. – Helps dry skin by properly distributing oils and water. ‘Repairs the skin and returns it to a healthy condition. – Relieves very dry and itchy skin,and also skin cracking – Stimulates skin cell renewal by reinvigorating old cells and generating new healthy cells.","concerns":"Dullness, Uneven Texture, Fine Wrinkles, Redness.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Avena Sativa (Oat) Kernel Flour, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, Biotin, Calcium Sulfate, Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate, Potassium Chloride, Iron Oxides, Fragrance. *Certified Organic Ingredients."}'::jsonb),
('mask', '781', 10, '{"code":"781","name":"Intensive Aftercare","dot":"#5A9E6E","tags":"Soothe · Recover","cats":["calm"],"img":"assets/products/us/781.jpg","desc":"BENEFITS – Effective anti-inflammatory prevents cell damage caused by free radicals. – Naturally soothing and helps reduce redness; has natural anti-microbial and antioxidant properties, and acts as a natural free radical scavenger. – Appropriate for use after harsh and intense treatments such as extractions, laser, peeling, or waxing. – Ability to eliminate nervous tension, relieve pain, disinfect skin, and inhibit bacteria that cause the initial infection. – Helps speed up the healing process. – Minimizes skin irritation, rashes, inflammation, and redness.","concerns":"Blemishes, Anti-Inflammatory, Ingrown Hair, Sensitive, Puffiness.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Lavandula Angustifolia (Lavender) Flower, Sodium Hyaluronate, *Avena Sativa (Oat) Kernel Flour, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, *Lavandula Angustifolia (Lavender) \u0003Flower Powder, Vitis Vinifera (Grape) Seed Extract, Phytonadione (Vitamin K), Bromelain (Ananas Comosus) Extract (Pineapple Stem), Calcium\u0003Sulfate, Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate, Potassium Chloride, Iron Oxides, Fragrance. *Certified Organic Ingredients."}'::jsonb),
('mask', '782', 11, '{"code":"782","name":"Hyaluronic Acid","dot":"#2E86C8","tags":"Plump · Replenish","cats":["hydrate"],"img":"assets/products/us/782.jpg","desc":"BENEFITS – Promotes SUPERIOR MOISTURE RETENTION – Penetrate skin and delivers intense hydration. – Restores and preserves moisture for glossy skin due to moisturizing components. Boosts skin moisture and plumps the surrounding tissues. – Improve moisture balance and maintains lipid balance by improving the skin’s barrier function and thereby reducing evaporation. – Promotes collagen synthesis to retain skin elasticity, firmness, and pliability.","concerns":"Dryness, Dullness, Redness, Wrinkles, Sensitive, Rosacea.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Avena Sativa (Oat) Kernel Flour, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, *Aloe Barbadensis Leaf Powder,\u0003 Calcium Sulfate, Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate, Potassium Chloride, Iron Oxides, Chromium Oxide Greens, Fragrance. *Certified Organic Ingredients. BETA-CAROTENE FLORAL INGREDIENTS: Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Calendula Officinalis Flower, Sodium Hyaluronate, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, *Calendula \u0003Officinalis Extract, Calcium Sulfate, Sodium Chloride, Diatomaceous Earth, Magnesium Sulfate, Potassium\u0003 Chloride, *Calendula Officinalis Flower Oil, Fragrance.*Certified Organic Ingredients. p.5 BRIGHTENING COMPLEX INGREDIENTS: Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Avena Sativa (Oat) Kernel Flour, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, *Citrus Limon \u0003(Lemon) Fruit Extract, Glutathione, Calcium Sulfate, Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate, \u0003Potassium Chloride, Iron Oxides, Fragrance. *Certified Organic Ingredients. p."}'::jsonb),
('mask', '783', 12, '{"code":"783","name":"Beta-Carotene Floral","dot":"#E08A2E","tags":"Protect · Glow","cats":["brighten"],"img":"assets/products/us/783.jpg","desc":"WHAT IT IS Beta-Carotene Floral Penetrates the skin’s surface for visibly diminished fine wrinkles and revitalized skin while delivering hydration throughout the day to improve the look of skin texture and tone. Speeds cell turnover, produces collagen, and unclogs pores. Ceramide delivers steady hydration, leaving the skin looking healthy and more illuminated. This provides a remarkable protective barrier that binds together cells for supple, healthy skin. Helps diminish drabness, dryness, and the appearance of fine lines.","concerns":"Dullness, Uneven Texture, Fine Lines, Wrinkles, Redness, Eczema.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Calendula Officinalis Flower, Sodium Hyaluronate, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, *Calendula Officinalis Extract, Calcium Sulfate, Sodium Chloride, Diatomaceous Earth, Magnesium Sulfate, Potassium Chloride, *Calendula Officinalis Flower Oil, Fragrance. *Certified Organic Ingredients."}'::jsonb),
('mask', '784', 13, '{"code":"784","name":"Cica Complexion Care","dot":"#D8C22E","tags":"Calm · Balance","cats":["calm"],"img":"assets/products/us/784.jpg","desc":"WHAT IT IS Gica Complex Care helps to increase blood flow to wounds, reduce the formation of excess scar tissues, and improve skin elasticity. It reduces the appearance of superficial and deep wrinkles, firming up the skin by increasing the synthesis of collagen and support the basic “glue” that holds our cells together. This formula diminishes the appearance of blemishes and restores the look of the skin’s strength health and vitality while enhancing the skin renewal process","concerns":"Acne, Scars, Sensitive, Blemishes, Bumps, Ingrown Hair.","ingredients":"Potassium Alginate, Algin, Jasminum Officinale (Jasmine) Flower, *Oryza Sativa (Rice) Powder, Sodium\u0003 Hyaluronate, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, *Centella Asiatica (Guto Kola) Extract, \u0003*Jasminum Officinale (Jasmine) Flower/Leaf Extract, Phytonadione (Vitamin K), Sodium Chloride, Calcium Sulfate, Diatomaceous Earth, Magnesium Sulfate, Potassium Chloride, Fragrance. *Certified Organic Ingredients. HYDROJELLY MASK R 27"}'::jsonb),
('mask', '785', 14, '{"code":"785","name":"Illuminating Orange","dot":"#E8822B","tags":"Brighten · Radiate","cats":["brighten"],"img":"assets/products/us/785.jpg","desc":"WHAT IT IS Illuminating Orange Peel has strong lightening properties but does not irritate the skin due its natural soothing effects. It is the top rated solution to pigmentation without harmful side effects. Glass-smooth skin rapidly increases brightness, radiance luminosity and vibrant glow. This illuminating formula helps to diffuse accumulated excess melanin, a cause of hyper-pigmentation, resulting in visibly illuminated skin tone . The brightening formula helps enhance tone, clarity, and visible brightening . It also diminishes the appearance of pores and reinforces the skin’s moisture barrier for a skin-smoothing glow.","concerns":"Discolorations, Hyperpigmentation, Dark Spots & Circles, Uneven Skin Tone.","ingredients":"Potassium Alginate, Algin, Citrus Aurantium Dulcis (Orange) Peel Powder, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, Niacinamide, Glutathione, *Citrus Aurantium Dulcis (Orange) Peel Extract, Calcium Sulfate, Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate, Potassium Chloride, Citrus Aurantium Dulcis (Orange) Oil, Fragrance. *Certified Organic Ingredients."}'::jsonb),
('mask', '786', 15, '{"code":"786","name":"Phyto-Nutrients Blast","dot":"#4A86A8","tags":"Nourish · Revitalize","cats":["calm"],"img":"assets/products/us/786.jpg","desc":"WHAT IT IS Phyto-Nutrients Blast is formulated with broccoli and plant-based collagen for a natural radiance, luminosity and vibrant glow-skin . It helps calm and soothe skin, acts as a balancing adaptogen, and protects hydrated, healthy skin. A targeted solution for dull skin, this supercharged, face mask brightens with broccoli extract and provides instant hydration. These superfoods promote a healthy, more youthful-looking glow and help improve general well-being and immunity. This diminishes the appearance of aging, supports the body’s natural antioxidant self-defense mechanisms, helps detoxify and nourish the body from the inside out, and helps defend against oxidative stress.","concerns":"Dullness, Uneven Texture, Dryness, Uneven Skin Tone, Sensitive.","ingredients":"Potassium Alginate, Algin, Lonicera Caprifolium (Honeysuckle) Extract, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Camellia Sinensis (Green Tea) Leaf, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix\u0003 Alba (Willow) Bark Extract, *Brassica Oleracea Italica (Broccoli) Extract, Calcium Sulfate, Sodium Chloride, Diatom\u0003aceous Earth, Magnesium Sulfate, Potassium Chloride, Fragrance. *Certified Organic Ingredients."}'::jsonb),
('mask', '787', 16, '{"code":"787","name":"Skin Warrior Ageless","dot":"#7D7F78","tags":"Firm · Restore","cats":["firm"],"img":"assets/products/us/787.jpg","desc":"WHAT IT IS Skin Warrior Ageless restores and rejuvenates the skin leaving it healthier, firmer, and much more radiant. Treat your skin with this refreshing formula infused with ginseng, known for its smoothing and moisturizing properties. Ginseng helps skin feel hydrated and smoothed, leaving behind a glowing complexion. Pat into the skin for an instant feeling of refreshing comfort for skin that is supremely soft. Helps strengthen the skin’s connective tissues and keeps the skin looking plump and smooth. Penetrates the skin’s surface to refresh, and restore radiance to tired skin.","concerns":"Loss of Firmness, Elasticity, Fine Lines, Wrinkles, Dullness.","ingredients":"Potassium Alginate, Algin, Nelumbo Nucifera Seed Powder, *Oryza Sativa (Rice) Powder, Sodium \u0003Hyaluronate, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, *Panax Ginseng\u0003 Root Extract, Ubiquinone, Calcium Sulfate, Sodium Chloride, Diatomaceous Earth, Magnesium Sulfate, Potassium\u0003 Chloride, Fragrance. *Certified Organic Ingredients."}'::jsonb),
('mask', '788', 17, '{"code":"788","name":"Purifying Activated Charcoal","dot":"#6E6A66","tags":"Detox · Purify","cats":["clarify"],"img":"assets/products/us/788.jpg","desc":"WHAT IT IS Purifying Actived Charcoal helps flush out environmental toxins, dirt, and debris. Lecithin dissolves impurities that can clog pores and cause common skin concerns, which include blemishes, redness, scars, razor bumps, and in-grown hairs. An ultra-purifying mask to deep clean and visibly reduce pores and clarify the complexion. It helps to cool and soothe the irritation, making it potentially useful against itchy, irritated, and infected skin.","concerns":"Acne, Blemishes, Redness, Ingrown Hair, Blackheads, Oiliness, Sensitive.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, *Charcoal Powder, Sodium Hyaluronate, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, *Bamboo Charcoal, Calcium \u0003Sulfate, Sodium Chloride, Diatomaceous Earth, Magnesium Sulfate, Potassium Chloride, Melaleuca Alternifolia\u0003 (Tea Tree) Leaf Oil, Mentha Piperita (Peppermint) Oil. *Certified Organic Ingredients."}'::jsonb),
('mask', '789', 18, '{"code":"789","name":"Vampire PLLA Infusion","dot":"#D0202E","tags":"Plump · Revive","cats":["firm"],"img":"assets/products/us/789.jpg","desc":"WHAT IT IS Collagen Infusion provides concentrated lifting POLY-L-LACTIC ACID (PLLA), which works with the skin’s natural renewal process to increase visible density and elasticity. This helps fill in the natural shape for a more sculpted look with firmer and plumper skin. The skin’s contours are given a defined and radiant look with diminished visible signs of aging. This illuminating treatment infuses the skin with sculpting power for an uplifted, refreshed look that tightens and firms the appearance of the face and neck. The result is skin that appears younger, radiant, and wide awake.","concerns":"Loss of Firmness, Elasticity, Sagging, Fine Lines, Wrinkles.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, Calcium Sulfate, Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate,\u0003 Potassium Chloride, Poly-L-lactide, Cellulose Gum, Mannitol, Carmine. *Certified Organic Ingredients."}'::jsonb),
('mask', '790', 19, '{"code":"790","name":"Spot Diminishing ALA","dot":"#2E7CC2","tags":"Clarify · Even","cats":["clarify"],"img":"assets/products/us/790.jpg","desc":"WHAT IT IS Spot Diminishing ALA treats acne-prone skin to shrink oil glands and minimize colonies of bacteria responsible for acne. Blue LED light with ALA penetrates the dermis to kill the bacteria that cause acne breakouts (P. acnes). The P. acnes bacteria can grow in the hair follicles and cause inflammation, which then blocks pores and turns into inflamed pimples. Also, it shrinks the sebaceous (oil-producing) glands of the skin. This reduces acne by decreasing the amount of oil in each pore (acne bacteria thrives on oil). This provides a natural antiseptic with antifungal, antiviral, anti-inflammatory, and antibacterial properties making it highly effective in treating wounds, acne, and skin infections.","concerns":"Acne (Papules, Cysts and Nodules), Oiliness, Ingrown Hair, Blemishes.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, Calcium Sulfate, Diatomaceous Earth, Sodium Chloride, \u0003Magnesium Sulfate, 5-Aminolevulinic acid, Potassium Chloride, Eucalyptus Globulus Leaf Oil, Mentha Piperita\u0003 (Peppermint) Oil, Ultramarines. *Certified Organic Ingredients."}'::jsonb),
('mask', '791', 20, '{"code":"791","name":"CBD 1000mg Dope","dot":"#6B7A2A","tags":"Calm · Balance","cats":["calm"],"img":"assets/products/us/791.jpg","desc":"CBD is a nearly perfect skin care extract suitable for all skin types. It shows significant promise as an anti-inflammatory, balancing skin hydration, helping oily skin, and controlling oil production.","concerns":"Breakouts, Acne-Prone, Sensitive, Redness, Eczema, Psoriasis, Rosacea, Atopic Dermatitis.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Camellia Sinensis (Green Tea) Leaf Powder, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract,\u0003 *Centella Asiatica (Gotu Kola) Extract, Calcium Sulfate, Diatomaceous Earth, Cannabidiol, Magnesium Sulfate, \u0003Potassium Chloride, Sodium Chloride, Chromium Oxide Greens. *Certified Organic Ingredients."}'::jsonb),
('mask', '792', 21, '{"code":"792","name":"Youthful Elixir","dot":"#C9A227","tags":"Luxury · Youth","cats":["firm"],"img":"assets/products/us/792.jpg","desc":"Supercharge your skincare with two luxurious ingredients: truffles and 24K gold. Truffle and gold belong to the highest level of skin care luxury because they work from the inside out.","concerns":"Suitable For All Skin Types.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, Mica, Glucose, *Cocos \u0003Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, White Truffles (Tuber Magnatum Pico Powder),\u0003 Summer Truffle (Tuber Aestivum Powder), Calcium Sulfate, Diatomaceous Earth, Gold (24K), Sodium Chloride, \u0003Magnesium Sulfate, Potassium Chloride. *Certified Organic Ingredients."}'::jsonb),
('mask', '793', 22, '{"code":"793","name":"LED Light See-Through","dot":"#B9BDC4","tags":"Protect · LED","cats":["calm"],"img":"assets/products/us/793.jpg","desc":"The LED Light See-Through Hydrojelly is a thin mask that protects the skin from dryness and irritation while allowing light waves to pass through the skin during LED light treatment.","concerns":"Suitable For All Skin Types.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, Glucose, *Cocos \u0003Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, *Sprouted Whole-Grain Brown Rice Protein,\u0003 *Camellia Sinensis (Green Tea) Leaf Powder, Calcium Sulfate, Diatomaceous Earth, Sodium Chloride, Magnesium\u0003 Sulfate, Arbutin, Potassium Chloride. *Certified Organic Ingredients."}'::jsonb),
('mask', '794', 23, '{"code":"794","name":"Discoloration Alpha Arbutin","dot":"#9B8FC4","tags":"Even · Correct","cats":["brighten"],"img":"assets/products/us/794.jpg","desc":"Alpha arbutin works by inhibiting tyrosinase activity to reduce the amount of melanin the skin produces. Less tyrosinase and less melanin mean a more even complexion with less pigmentation, fewer dark spots, and less noticeable acne scars.","concerns":"Hyperpigmentation, Discoloration, Age Spots, Melasma.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, Glucose, *Cocos \u0003Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, Alpha- Arbutin, Glutathione, Calcium Sulfate, \u0003Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate, Potassium Chloride, D&C Red No.6, D&C Yellow\u0003No.5, Carmine. *Certified Organic Ingredients."}'::jsonb),
('mask', '795', 24, '{"code":"795","name":"Chi Energy Infused","dot":"#8E6FB8","tags":"Balance · Energize","cats":["calm"],"img":"assets/products/us/795.jpg","desc":"Chi, also pronounced as Ki, is the word for the life force energy that flows through every living thing. Crystals in Chi Energy Infused Hydrojelly have powerful healing energy and act as conduits for healing, allowing positive energy to flow into the body as negative energy flows out.","concerns":"Anti-Blemish & Anti-Inflammatory, Energy Balance.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, Portulaca Oleracea Extract, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Salix Alba (Willow) Bark Extract, Camellia Sinensis (Green Tea) Leaf Powder, *Centella\u0003 Asiatica (Gotu Kola) Extract, Calcium Sulfate, Diatomaceous Earth, Magnesium Sulfate, Potassium Chloride, Sodium Chloride, Chromium \u0003Oxide Greens, Rose Quartz, Amethyst, Green Jade Aventurine, Black Obsidian, Clear Quartz. *Certified Organic Ingredients."}'::jsonb),
('mask', '796', 25, '{"code":"796","name":"Blue Glacier Cryo","dot":"#7FB6D9","tags":"Cool · De-Puff","cats":["calm"],"img":"assets/products/us/796.jpg","desc":"Cool temperatures can help calm inflammation and control pigmentation to brighten the skin. Cold therapy shrinks blood vessels and causes the muscles of the face to constrict, reducing swelling, dark circles, and patches.","concerns":"Instant Freshness, Anti-Blemish, Instant Cooling and Soothing, Anti-Swelling.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Cocos Nucifera (Coconut) Fruit Powder, Glacial Clay, Glucose, *Salix Alba (Willow) Bark Extract, *Mentha Viridis (Spearmint) Leaf, Xylitol, *Centella Asiatica (Guto Kola) Extract, Calcium Sulfate, Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate, Potassium Chloride, Ultramarines. *Certified Organic Ingredients."}'::jsonb),
('mask', '797', 26, '{"code":"797","name":"Rosehip Hop","dot":"#C96A85","tags":"Nourish · Calm","cats":["hydrate"],"img":"assets/products/us/797.jpg","desc":"This beauty unicorn delivers luminous and younger-looking skin, no matter the skin condition. Rosehip Hop Hydrojelly Mask moisturizes skin naturally without adding excess oil and improves skin''s moisture barrier function. It helps calm sensitive skin or skin suffering from irritation and redness.","concerns":"Dryness, Dullness, Irritated & Inflamed.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Rosa Canina (Rosehip) Fruit Extract, *Cocos Nucifera (Coconut) Fruit Powder, Glucose, *Salix Alba (Willow) Bark Extract, Calcium Sulfate, Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate, Potassium Chloride. *Certified Organic Ingredients."}'::jsonb),
('mask', '798', 27, '{"code":"798","name":"AHA BHA","dot":"#E8A15A","tags":"Exfoliate · Smooth","cats":["clarify"],"img":"assets/products/us/798.jpg","desc":"This powerful antioxidant fruit (organic pumpkin & organic papaya) enzyme exfoliates to improve the appearance of dull, aging, and congested skin. It helps even out skin tone and smooth the appearance of fine lines and wrinkles, revealing skin that appears smoother, more radiant, and revitalized.","concerns":"Uneven Texture, Uneven Tone, Tired or Dry Skin.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Cucurbita Pepo (Pumpkin) Powder, *Carica Papaya (Papaya) Fruit Extract, *Cocos Nucifera (Coconut) Fruit Powder, Glucose, *Salix Alba (Willow) Bark Extract, Calcium Sulfate, Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate, Potassium Chloride, Iron Oxides. *Certified Organic Ingredients."}'::jsonb),
('mask', '799', 28, '{"code":"799","name":"Green Tea Tree","dot":"#4E7A46","tags":"Clarify · Soothe","cats":["clarify","calm"],"img":"assets/products/us/799.jpg","desc":"Tea tree and Matcha extract are the best combination of ingredients to calm redness, swelling, and inflammation. They also help to reduce the appearance of acne and to remove surface oils without over-drying or causing irritation.","concerns":"All Skin Types, Sensitive, Dullness, Inflamed.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Camellia Sinensis (Green Matcha) Leaf Powder, *Melaleuca Alternifolia (Tea Tree) Leaf Oil, *Cocos Nucifera (Coconut) Fruit Powder, Glucose, *Salix Alba (Willow) Bark Extract, Calcium Sulfate, Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate, Potassium Chloride, Chromium Oxide Greens. *Certified Organic Ingredients."}'::jsonb),
('mask', '800', 29, '{"code":"800","name":"Glutathione","dot":"#B9C0C6","tags":"Bright · Pure","cats":["brighten"],"img":"assets/products/us/800.jpg","desc":"Glutathione is a powerful antioxidant that can provide a range of benefits for the skin. It can reduce the appearance of hyperpigmentation and UV spots, brighten the skin, and purify the skin by removing toxins and impurities.","concerns":"Hyperpigmentation & UV Spots.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Cocos Nucifera (Coconut) Fruit Powder, Glucose, *Salix Alba (Willow) Bark Extract, Glutathione, Calcium Sulfate, Niacinamide, Diatomaceous Earth, Alpha-Arbutin, Sodium Chloride, Magnesium Sulfate, Potassium Chloride, Manganese Violet. *Certified Organic Ingredients. SALMON DNA PDRN p."}'::jsonb),
('mask', '801', 30, '{"code":"801","name":"Retinol Alternative","dot":"#86A17B","tags":"Renew · Smooth","cats":["firm"],"img":"assets/products/us/801.jpg","desc":"Bakuchiol mimics the effects of a retinol-like alternative derived from the babchi plant, with the advantage of not causing irritation. The plant extract diminishes fine lines and wrinkles, boosts collagen production, smooths the texture of your complexion, clears up hyperpigmentation, and promotes skin cell renewal.","concerns":"Fine Lines and Wrinkles, Loss of Firmness and Elasticity.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Cocos Nucifera (Coconut) Fruit Powder, Glucose, *Salix Alba (Willow) Bark Extract, Bakuchiol, Calcium Sulfate, Diatomaceous Earth, Niacinamide, Sodium Chloride, Hydrolyzed Silk Peptide, Magnesium Sulfate, Potassium Chloride, Iron Oxides, Oxide Greens. *Certified Organic Ingredients. INGREDIENTS: Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Malpighia Emarginata (Acerola) Fruit Powder, *Vaccinium Angustifolium (Blueberry) Fruit Extract, *Fragaria Ananassa (Strawberry) Fruit Powder, Sodium DNA (PDRN), *Salix Alba (Willow) Bark Extract, Calcium Sulfate, Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate, Arbutin, Potassium Chloride, Fragrance. *Certified Organic Ingredients."}'::jsonb),
('mask', '802', 31, '{"code":"802","name":"Wildcrafted Sea Moss","dot":"#4C8D7E","tags":"Mineral · Soothe","cats":["hydrate","calm"],"img":"assets/products/us/802.jpg","desc":"Sea moss contains an impressive 92 of the 102 essential nutrients, many of which are beneficial for skin health. Its nutrient-dense composition provides rapid moisture to soothe irritated and inflamed skin, especially for those with inflammatory skin conditions like acne and rosacea.","concerns":"All Skin Types, Dry & Dull, Irritated & Inflamed.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Cocos Nucifera (Coconut) Fruit Powder, Glucose, *Salix Alba (Willow) Bark Extract, *Chondrus Crispus, *Aloe Barbadensis Leaf Powder, Calcium Sulfate, *Euterpe Oleracea Mart, Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate, Potassium Chloride, Ultramarines, Iron Oxides. *Certified Organic Ingredients."}'::jsonb),
('mask', '803', 32, '{"code":"803","name":"NAD+ Longevity","dot":"#29508F","tags":"Longevity · Repair","cats":["firm"],"img":"assets/products/us/803.jpg","desc":"NAD+ (Nicotinamide Adenine Dinucleotide) is a coenzyme found in all living cells that plays a crucial role in various biological processes, including energy metabolism and DNA repair. Its levels decline as we age, which leads to a decrease in cellular function and an increase in cellular aging and damage.","concerns":"Mature & Aging, Damaged & Stressed, Dull & Sagging.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Cocos Nucifera (Coconut) Fruit Powder, Glucose, *Salix Alba (Willow) Bark Extract, Nicotinamide Adenine Dinucleotide, Calcium Sulfate, Niacinamide, Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate, Potassium Chloride, Chromium, Iron Oxides. *Certified Organic Ingredients."}'::jsonb),
('mask', '804', 33, '{"code":"804","name":"Silk Cocoon Peptide","dot":"#D8CDB8","tags":"Silk · Protect","cats":["firm","hydrate"],"img":"assets/products/us/804.jpg","desc":"The cocoon of the silkworm converts silk to fibrous proteins (collagen threads). The molecular structure of silk proteins is similar to that of the collagen fibers that make up human skin. Silk proteins naturally help to form a layer of protection over the skin to help lock in essential moisture.","concerns":"Anti-Aging, Dryness, Fine Lines & Wrinkles, Loss of Firmness & Elasticity.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Cocos Nucifera (Coconut) Fruit Powder, Glucose, *Salix Alba (Willow) Bark Extract, Hydrolyzed Silk Peptide, Calcium Sulfate, Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate, Potassium Chloride, Mica, Fragrance. *Certified Organic Ingredients."}'::jsonb),
('mask', '805', 34, '{"code":"805","name":"Salmon DNA PDRN","dot":"#F2A099","tags":"Repair · Renew","cats":["firm"],"img":"assets/products/us/805.jpg","desc":"Salmon DNA PDRN is a low molecular weight DNA extract that stimulates skin regeneration at the cellular level. Originally used in wound healing and tissue repair in medical fields, it is now a premium anti-aging ingredient in aesthetic skincare. It stimulates skin regeneration by activating fibroblasts to produce collagen and repair damaged tissue.","concerns":"Skin Regeneration, Tissue Repair, Anti-Aging.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, Glucose, *Cocos Nucifera (Coconut) Fruit Powder, *Malpighia Emarginata (Acerola) Fruit Powder, *Vaccinium Angustifolium (Blueberry) Fruit Extract, *Fragaria Ananassa (Strawberry) Fruit Powder, Sodium DNA, Salix Alba (Willow) Bark Extract, Calcium Sulfate, Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate, Arbutin, Potassium Chloride, Fragrance. *Certified Organic Ingredients."}'::jsonb),
('mask', '806', 35, '{"code":"806","name":"Discoloration Corrector","dot":"#E3A66B","tags":"Fade · Even","cats":["brighten"],"img":"assets/products/us/806.jpg","desc":"Helps reduce hyperpigmentation caused by sun exposure, medical treatments, or acne. Powered by a concentrated blend of Tranexamic Acid, Ferulic Acid, and Alpha Tocopherol, this advanced complex effectively fades stubborn dark spots and post-inflammatory discoloration, promoting a more even skin tone.","concerns":"Hyperpigmentation, Uneven Skin Tone, Anti-Aging, Post-Inflammatory Discoloration, Acne Scars.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, Glucose, *Cocos Nucifera\u0003 (Coconut) Fruit Powder, *Malpighia Emarginata (Acerola) Fruit Powder, *Salix Alba (Willow) Bark Extract, *Fragaria Ananassa\u0003 (Strawberry) Fruit Powder, Calcium Sulfate, Diatomaceous Earth, Sodium Chloride, Magnesium Sulfate, Arbutin, Ascorbic \u0003Acid, Tranexamic Acid, Tocopherol, Ferulic Acid, Potassium Chloride, Fragrance. *Certified Organic Ingredients."}'::jsonb),
('mask', '807', 36, '{"code":"807","name":"CO2 Carboxy","dot":"#3E5A5E","tags":"Oxygenate · Revive","cats":["clarify"],"img":"assets/products/us/807.jpg","desc":"A powerful skin-reviving Hydrojelly mask that uses CO₂ (Carbon Dioxide) Carboxy Therapy, combined with Citric, Humic, and Fulvic Acids, to deeply oxygenate the skin, remove toxins, and energize tired or aging skin, all without injections.","concerns":"Dull, Tired & Oxygen-Deprived Skin, Sensitive, Inflamed & Congested Skin.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, *Cocos Nucifera (Coconut) Fruit Powder, Glucose, *Salix Alba (Willow) Bark Extract, *Aloe Barbadensis Leaf Extract, Magnesium Carbonate, Sodium Cocoyl Isethionate, Sodium Lauryl Sulfate, Sodium Bicarbonate, Sodium Chloride, Magnesium Sulfate, Sodium Palmitate, Sodium Lauroyl Glutamate, Mica, Diglycerin, Sodium Lauroyl Aspartate, Citric Acid, Allantoin, Maltodextrin, Calcium Carbonate, Calcium Sulfate, Diatomaceous Earth, Potassium Chloride, Humic Acid, Fulvic\u0003 Acid, Melaleuca Alternifolia (Tea Tree) Leaf Oil, Ultramarines.*Certified Organic Ingredients."}'::jsonb),
('mask', '808', 37, '{"code":"808","name":"I Love You So Matcha","dot":"#7A9B5E","tags":"Calm · Refresh","cats":["calm"],"img":"assets/products/us/808.jpg","desc":"Powered by antioxidant-rich Matcha Green Tea, this mask helps soothe, purify, and deeply hydrate stressed skin for a refreshed, healthy-looking glow. Rich in polyphenols, catechins, chlorophyll, vitamins, and minerals, it helps protect against environmental stressors and visible signs of aging.","concerns":"Ideal for Stressed, Oily, Combination, and Dull Skin.","ingredients":"Potassium Alginate, Algin, *Oryza Sativa (Rice) Powder, Sodium Hyaluronate, Glucose, *Cocos\u0003 Nucifera (Coconut) Fruit Powder, *Camellia Sinensis Leaf (Matcha) Powder, *Spirulina Platensis Powder, *Salix\u0003 Alba (Willow) Bark Extract, Calcium Sulfate, Diatomaceous Earth, Mica, Sodium Chloride, Magnesium Sulfate,\u0003 Potassium Chloride, Chlorophyllin-Copper Complex, Chromium Oxide Greens. *Certified Organic Ingredients."}'::jsonb),
('skincare', 'hydro-serum', 0, '{"slug":"hydro-serum","name":"Hydro Serum","code":"933","category":"Serum","size":"3.38 FL.OZ / 100 ML","desc":"Urea is a powerful humectant that hydrates and moisturizes the skin to give a softer texture by providing instant relief for dry, itchy skin. It aids the skin back to health by strengthening the skin''s protective barrier to help moisture stay within the skin.","concerns":"Anti-Dryness, Even Skin Texture, Glowing.","ingredients":"Water, Glycerin, Hamamelis Virginiana (Witch Hazel) Extract, Centella Asiatica Leaf Water, Camellia Sinensis Leaf Water, Butylene Glycol, Sodium Hyaluronate, Tocopheryl Acetate, Sorbitol, Urea, Allantoin, Panthenol, Carbomer, Polyglyceryl-10 Laurate, Triethanolamine, Hydroxyethylcellulose, Disodium EDTA, 1,2-Hexanediol, Allura Red AC, Fragrance.","img":"assets/products/skincare/hydro-serum.jpg"}'::jsonb),
('skincare', 'ala-13-serum', 1, '{"slug":"ala-13-serum","name":"ALA-13 Serum","code":"934","category":"Serum","size":"3.38 FL.OZ / 100 ML","desc":"Blue LED light with 5-Aminolevulinic Acid HCl (ALA) penetrates the dermis to kill the bacteria that causes acne breakouts (P. acnes). The P. acnes bacteria grow in the hair follicles and cause inflammation, which then blocks pores and turns into inflamed pimples.","concerns":"Acne Treatment with Blue LED Light.","ingredients":"Water, Glycerin, Hamamelis Virginiana (Witch Hazel) Extract, Centella Asiatica Leaf Water, Camellia Sinensis Leaf Water, Butylene Glycol, Sodium Hyaluronate, Aminolevulinic Acid HCl, Tocopheryl Acetate, Centella Asiatica Extract, Portulaca Oleracea Extract, Ananas Sativus (Pineapple) Fruit Extract, Allantoin, Panthenol, Carbomer, Triethanolamine, Polyglyceryl-10 Laurate, Hydroxyethylcellulose, Disodium EDTA, 1,2-Hexanediol, Sunset Yellow FCF, Brilliant Blue FCF, Fragrance.","img":"assets/products/skincare/ala-13-serum.jpg"}'::jsonb),
('skincare', 'hyaluronic-acid-100', 2, '{"slug":"hyaluronic-acid-100","name":"Hyaluronic Acid 100","code":"573","category":"Serum","size":"3.38 FL.OZ / 100 ML","desc":"An ideal serum for dry, dehydrated skin, this serum contains a mega-dose of hyaluronic acid which boosts skin moisture retention to help the skin hold onto hydration longer. Hyaluronic acid deeply moisturizes and improves skin elasticity by holding up to 5,000 times its weight in water.","concerns":"Dry, Dull, All Skin Types.","ingredients":"Water, Sodium Hyaluronate, 1,2-Hexanediol, Ethylhexylglycerin.","img":"assets/products/skincare/hyaluronic-acid-100.jpg"}'::jsonb),
('skincare', 'nano-egf-serum', 3, '{"slug":"nano-egf-serum","name":"Nano EGF Serum","code":"938","category":"Serum","size":"3.38 FL.OZ / 100 ML","desc":"Epidermal Growth Factor (EGF) is an age-prevention ingredient that can help with cell renewal and wound repair for the skin. As we age, our EGF levels decrease causing mature, saggy skin. EGF is a significant protein found in fibroblast cells that can work to stimulate the skin to restore the collagen process.","concerns":"Age-Prevention, Renewing, Anti-Sagging.","ingredients":"Water, Glycerin, Hamamelis Virginiana (Witch Hazel) Extract, Centella Asiatica Leaf Water, Camellia Sinensis Leaf Water, Butylene Glycol, sh-Oligopeptide-1, Simmondsia Chinensis (Jojoba) Seed Oil, Squalane, Ceramide NP, Sodium Hyaluronate, Tocopheryl Acetate, Polyglyceryl-10 Laurate, Panthenol, Carbomer, Betaine, Sodium PCA, Proline, Threonine, Glutamic Acid, Lysine, Alanine, Sorbitol, Glycine, Serine, Triethanolamine, Styrene/VP Copolymer, Hydroxyethylcellulose, Octyldodecanol, Disodium EDTA, Hydrogenated Lecithin, 1,2-Hexanediol, Caprylic/Capric Triglyceride, Sodium Dodoxynol-40 Sulfate, Cholesterol, Sorbic Acid, Fragrance.","img":"assets/products/skincare/nano-egf-serum.jpg"}'::jsonb),
('skincare', 'electrolyte-dewy-cream', 4, '{"slug":"electrolyte-dewy-cream","name":"Electrolyte Dewy Cream","code":"432","category":"Innovation Cream","size":"7.60 FL.OZ / 225 ML","desc":"Electrolyte Dewy Cream evens the skin''s natural moisture balance and helps the skin maintain its natural moisture barrier. This helps the skin hold onto moisture and prevent dryness.","concerns":"Dryness, Dullness, Redness, Wrinkles, Sensitive, Rosacea.","ingredients":"Water, Dimethicone, Glycerin, Butylene Glycol, Cyclopentasiloxane, Hydrogenated Polyisobutene, Centella Asiatica Extract, Cyclohexasiloxane, Centella Asiatica Leaf Water, Hamamelis Virginiana (Witch Hazel) Water, Chamomilla Recutita (Matricaria) Flower Water, Sodium Hyaluronate, Hamamelis Virginiana (Witch Hazel) Leaf Extract, Cocos Nucifera (Coconut) Liquid Endosperm, Malpighia Glabra (Acerola) Fruit Extract, Vaccinium Angustifolium (Blueberry) Fruit Extract, Aloe Barbadensis Leaf Juice, Rosmarinus Officinalis (Rosemary) Leaf Extract, Chamomilla Recutita (Matricaria) Flower Extract, Ceramide NP, Simmondsia Chinensis (Jojoba) Seed Oil, Squalane, Allantoin, Proline, Threonine, Glutamic Acid, Lysine, Alanine, Sorbitol, Glycine, Serine, Betaine, Cetyl PEG/PPG-10/1 Dimethicone, Sodium Chloride, 1,2-Hexanediol, Octyldodecanol, Hydrogenated Lecithin, Caprylic/Capric Triglyceride, Cholesterol, Sodium PCA, Disodium EDTA.","img":"assets/products/skincare/electrolyte-dewy-cream.jpg"}'::jsonb),
('skincare', '24k-gold-flex-cream', 5, '{"slug":"24k-gold-flex-cream","name":"24K Gold Flex Cream","code":"431","category":"Innovation Cream","size":"7.60 FL.OZ / 225 ML","desc":"Gold has anti-inflammatory properties, making it ideal for those with dull, sensitive skin, hyperpigmentation, and acne scars. It also improves skin elasticity, firms the skin, and helps combat environmental stressors and pollutants.","concerns":"Suitable For All Skin Types, Anti-Aging.","ingredients":"Water, Rosa Damascena Flower Water, Melaleuca Alternifolia (Tea Tree) Leaf Water, Centella Asiatica Leaf Water, Camellia Sinensis Leaf Water, Glycerin, Petrolatum, Isopropyl Myristate, Butylene Glycol, Caprylic/Capric Triglyceride, Cetearyl Alcohol, Niacinamide, Glyceryl Stearate, Dimethicone, Palmitic Acid, Stearic Acid, Polysorbate 60, Gold, Hamamelis Virginiana (Witch Hazel) Leaf Extract, Olea Europaea (Olive) Fruit Oil, Vaccinium Angustifolium (Blueberry) Fruit Extract, Rosmarinus Officinalis (Rosemary) Leaf Extract, Melaleuca Alternifolia (Tea Tree) Extract, Jasminum Grandiflorum (Jasmine) Flower Extract, Adenosine, Tocopheryl Acetate, Sodium Hyaluronate, Hydrolyzed Collagen, Carbomer, Allantoin, 1,2-Hexanediol, Polyglyceryl-3 Methylglucose Distearate, Sorbitan Sesquioleate, Isopropyl Palmitate, Triethanolamine, Disodium EDTA, Myristic Acid, Arachidic Acid, Oleic Acid, Fragrance.","img":"assets/products/skincare/24k-gold-flex-cream.jpg"}'::jsonb),
('skincare', 'normal-cleanser', 6, '{"slug":"normal-cleanser","name":"Normal Cleanser","code":"102","category":"Cleanser","size":"33.81 FL.OZ / 1000 ML","desc":"Stearic acid (amino acid) helps remove dirt, sweat, and excess sebum from the skin. Vitamin E, one of the most powerful antioxidants, neutralizes the oxidative effects of free radicals, which can damage collagen and contribute to skin dryness, fine lines, and wrinkles.","concerns":"Cleanser For All Skin Types.","ingredients":"Water, Isopropyl Myristate, Polysorbate 60, Glyceryl Stearate, Cetearyl Alcohol, Portulaca Oleracea Extract, Carica Papaya (Papaya) Fruit Extract, Allantoin, Panthenol, Butylene Glycol, Carbomer, Tromethamine, Isopropyl Palmitate, 1,2-Hexanediol, Disodium EDTA, Fragrance.","img":"assets/products/skincare/normal-cleanser.jpg"}'::jsonb),
('skincare', 'lemon-soft-peeling-gel', 7, '{"slug":"lemon-soft-peeling-gel","name":"Lemon Soft Peeling Gel","code":"118","category":"Cleanser","size":"33.81 FL.OZ / 1000 ML","desc":"Niacinamide helps improve skin elasticity and enhances intercellular lipid synthesis, dramatically strengthening the skin''s barrier function. It helps restore discoloration, reduce rosacea, and revives skin''s healthy tone and texture. Lemon extract, an astringent, aids in detoxing impurities.","concerns":"Exfoliates and Deep Cleans.","ingredients":"Water, Butylene Glycol, Cellulose, Carica Papaya (Papaya) Fruit Extract, Citrus Limon (Lemon) Fruit Extract, Phaseolus Radiatus Seed Extract, Citrus Aurantium Dulcis (Orange) Fruit Extract, Fragaria Chiloensis (Strawberry) Fruit Extract, Niacinamide, Arginine, Carbomer, Benzyl Glycol, 1,2-Hexanediol, Ethylhexylglycerin, Propanediol, Polyglyceryl-10 Laurate, Cetyl Ethylhexanoate, Tartrazine, Fragrance.","img":"assets/products/skincare/lemon-soft-peeling-gel.jpg"}'::jsonb),
('skincare', 'sun-spf50', 8, '{"slug":"sun-spf50","name":"Sun (SPF 50+ PA++++)","code":"426","category":"Sun","size":"1.76 FL.OZ / 50 ML","desc":"SUN SPF50++++ contains Hyaluronic Acid: a Natural Moisture Factor that penetrates the skin''s upper layers to improve and benefit the skin. It reaches the dermis, boosting elasticity and hydration.","concerns":"Blocks UV Rays, Sun Protection.","ingredients":"Water, Zinc Oxide, Methyl Trimethicone, Butylene Glycol, Caprylyl Methicone, Polyglyceryl-4 Isostearate, Niacinamide, Cetyl PEG/PPG-10/1 Dimethicone, Hexyl Laurate, Sodium Chloride, Adenosine, Lilium Tigrinum Extract, Freesia Refracta Extract, Hydrolyzed Collagen, Salix Alba (Willow) Bark Extract, Sodium Hyaluronate, Beeswax, Allantoin, Triethoxycaprylylsilane, Sorbitan Sesquioleate, Ethylhexylglycerin, 1,2-Hexanediol, Dipotassium Glycyrrhizate, Fragrance.","img":"assets/products/skincare/sun-spf50.jpg"}'::jsonb),
('skincare', 'enzyme-powder', 9, '{"slug":"enzyme-powder","name":"Enzyme Powder","code":"113","category":"Enzyme Powder","size":"7.60 FL.OZ / 225 ML","desc":"Enzyme powder is a cleansing mask that naturally breaks down dead skin cells and other impurities, gently buffing them away as you cleanse.","concerns":"Cleanser For All Skin Types.","ingredients":"Zea Mays (Corn) Starch, Sodium Cocoyl Isethionate, Sodium Lauryl Sulfate, Sodium Palmitate, Sodium Lauroyl Glutamate, Diglycerin, Sodium Lauroyl Aspartate, Titanium Dioxide, Allantoin, Maltodextrin, Papain.","img":"assets/products/skincare/enzyme-powder.jpg"}'::jsonb),
('skincare', 'moisture-skin-solution', 10, '{"slug":"moisture-skin-solution","name":"Moisture Skin Solution","code":"312","category":"Toner & Emulsion","size":"33.81 FL.OZ / 1000 ML","desc":"This toner penetrates the dermis, boosting the skin''s elasticity and hydration. It plays an important role in cell protection, hydration, lubrication, and maintaining the structural integrity of the skin. The well-balanced botanical blend helps control sebum production, combat bacteria, and balance the skin''s pH level.","concerns":"Dryness, Acne, All Skin Types.","ingredients":"Water, Butylene Glycol, Glycerin, Niacinamide, Rosa Centifolia Flower Water, Hamamelis Virginiana (Witch Hazel) Extract, Hydrolyzed Collagen, Sodium Hyaluronate, Magnolia Liliflora Flower Extract, Rehmannia Chinensis Root Extract, Prunus Armeniaca (Apricot) Kernel Extract, Panax Ginseng Root Extract, Polygonum Multiflorum Root Extract, Dioscorea Opposita (Wild Yam) Root Extract, Ophiopogon Japonicus Root Extract, Betaine, Polyglyceryl-10 Laurate, Panthenol, 1,2-Hexanediol, Disodium EDTA, Carbomer, Triethanolamine, Fragrance.","img":"assets/products/skincare/moisture-skin-solution.jpg"}'::jsonb),
('skincare', 'vitamin-massage-cream', 11, '{"slug":"vitamin-massage-cream","name":"Vitamin Massage Cream","code":"212","category":"Massage Cream","size":"33.81 FL.OZ / 1000 ML","desc":"Massage for 15 to 20 minutes, then remove with wet towels. Ascorbic acid (Vitamin C) supports collagen growth and protection. Collagen helps maintain skin elasticity, delaying the appearance of wrinkles. Lemon Peel Extract (Vitamin C & P) enhances skin clarity, glow, and softness, it cleanses, lightens, brightens the skin, removes dead cells, and stimulates new skin growth.","concerns":"Nourishes, Moisturizes, Improves Skin Tone.","ingredients":"Mineral Oil, Water, Petrolatum, Propylene Glycol, Polysorbate 60, Beeswax, Dimethicone, Ceresin, Fragrance, Glycerin, Stearic Acid, Microcrystalline Wax, Carica Papaya (Papaya) Fruit Extract, Aloe Barbadensis Leaf Juice, Acer Saccharum (Sugar Maple) Extract, Citrus Aurantium Dulcis (Orange) Fruit Extract, Vaccinium Myrtillus Fruit/Leaf Extract, Saccharum Officinarum (Sugarcane) Extract, Citrus Limon (Lemon) Fruit Extract, 3-O-Ethyl Ascorbic Acid, Tocopheryl Acetate, Xanthan Gum, Cetearyl Alcohol, Glyceryl Stearate, Sorbitan Sesquioleate, PEG-100 Stearate, Triethanolamine, 1,2-Hexanediol, Lithium Magnesium Sodium Silicate, Disodium EDTA, Tartrazine.","img":"assets/products/skincare/vitamin-massage-cream.jpg"}'::jsonb),
('skincare', 'collagen-massage-cream', 12, '{"slug":"collagen-massage-cream","name":"Collagen Massage Cream","code":"213","category":"Massage Cream","size":"33.81 FL.OZ / 1000 ML","desc":"Massage for 15 to 20 minutes, then remove with wet towels. Hydrolyzed Collagen, a mixture of small peptides that break down into even smaller fragments, penetrating the skin''s surface, firms the skin and reduces the effects of aging as the collagen is absorbed. Vitamin E, one of the most powerful antioxidants, helps reduce the appearance of fine lines and wrinkles.","concerns":"Moisturizes, Energizes, Improves Skin Elasticity.","ingredients":"Mineral Oil, Water, Petrolatum, Propylene Glycol, Polysorbate 60, Beeswax, Dimethicone, Ceresin, Microcrystalline Wax, Stearic Acid, Glycerin, Acer Saccharum (Sugar Maple) Extract, Citrus Aurantium Dulcis (Orange) Fruit Extract, Vaccinium Myrtillus Fruit/Leaf Extract, Saccharum Officinarum (Sugarcane) Extract, Citrus Limon (Lemon) Fruit Extract, Hydrolyzed Collagen, Tocopheryl Acetate, Xanthan Gum, Glyceryl Stearate, Cetearyl Alcohol, Sorbitan Sesquioleate, PEG-100 Stearate, Triethanolamine, 1,2-Hexanediol, Lithium Magnesium Sodium Silicate, Disodium EDTA, Butylene Glycol, Allura Red AC, Fragrance.","img":"assets/products/skincare/collagen-massage-cream.jpg"}'::jsonb),
('skincare', 'aloe-gel', 13, '{"slug":"aloe-gel","name":"Aloe Gel","code":"332","category":"Body Cream & Gel","size":"33.81 FL.OZ / 1000 ML","desc":"Effective in treating a variety of skin conditions, such as flaky or dry skin, it provides oxygen to the skin, strengthening the skin tissue and keeping it healthy. The rose water extract soothes irritated skin and reduces redness.","concerns":"Fine Lines & Wrinkles, Hydrates & Rejuvenates, Sunspot Damages.","ingredients":"Water, Butylene Glycol, Glycerin, Aloe Barbadensis Leaf Extract, Rosa Damascena Flower Water, Centella Asiatica Extract, Hamamelis Virginiana (Witch Hazel) Extract, Cucumis Sativus (Cucumber) Fruit Extract, Portulaca Oleracea Extract, Allantoin, Carbomer, Tromethamine, Polyglyceryl-10 Laurate, 1,2-Hexanediol, Disodium EDTA, Maltodextrin, Hydroxyethylcellulose, Fragrance.","img":"assets/products/skincare/aloe-gel.jpg"}'::jsonb),
